const evidence=[{kind:'Primary record',text:'Payment voucher shows KSh 38.4M paid to Medisource Example Ltd.',state:'Documented'},{kind:'Field check',text:'Two sampled clinics could not locate the listed equipment serial numbers.',state:'Investigative finding'},{kind:'Missing record',text:'Inspection and acceptance certificate not present in the obtained procurement file.',state:'Unresolved'},{kind:'Company record',text:'Supplier was incorporated 73 days before the award.',state:'Context only'}];const wire=[{time:'21:14',kind:'MONEY',headline:'Kijani clinic equipment payment added to evidence chain',state:'DOCUMENTED',href:'#demo'},{time:'20:47',kind:'CORRECTION',headline:'Company match split after registry-number conflict',state:'CORRECTED',href:'#corrections'},{time:'19:32',kind:'CONTRACT',headline:'Synthetic county award added; no misconduct inference',state:'PUBLIC RECORD',href:'#demo'},{time:'17:08',kind:'EVIDENCE',headline:'Acceptance certificate remains missing from obtained file',state:'UNRESOLVED',href:'#demo'},{time:'15:41',kind:'METHOD',headline:'Coverage gap opened: asset ownership not yet searched',state:'OPEN',href:'#method'}];const el=document.getElementById('evidence');evidence.forEach(x=>{const d=document.createElement('div');d.className='evidence';d.innerHTML=`<div class="kind">${x.kind}</div><div>${x.text}</div><div class="state">${x.state}</div>`;el.appendChild(d)});const wr=document.getElementById('wireRows');wire.forEach(x=>{const d=document.createElement('div');d.className='wire-row';d.innerHTML=`<div class="time">${x.time}</div><div class="kind">${x.kind}</div><div class="headline"><a href="${x.href}">${x.headline}</a></div><div class="state">${x.state}</div>`;wr.appendChild(d)});const doctrine='FRAME UNIVERSE BLIND-SPOT VIEWPOINT PROVENANCE RIVALS CAUSALITY INVERSION TRANSFER STOP'.split(' ');const dd=document.getElementById('doctrine');doctrine.forEach(x=>{const s=document.createElement('span');s.textContent=x;dd.appendChild(s)});function setMode(mode){document.querySelectorAll('.navtab').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));document.querySelectorAll('.mode-brief').forEach(x=>x.hidden=mode!=='brief');document.querySelectorAll('.mode-wire').forEach(x=>x.hidden=mode!=='wire');if(mode==='wire')document.getElementById('wire').scrollIntoView({behavior:'smooth',block:'start'})}document.querySelectorAll('.navtab').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));document.querySelectorAll('[data-switch]').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.switch)));document.getElementById('searchBtn').addEventListener('click',()=>{const q=document.getElementById('q').value.toLowerCase();const m=document.getElementById('searchMsg');m.textContent=(q.includes('clinic')||q.includes('kijani')||q.includes('medisource'))?'1 synthetic demonstration dossier found below.':'No prototype record found. Production search will span entities, cases, contracts, assets, movements and evidence.'});